class Solution:
    def maxHeightOfTriangle(self, red, blue):
        def h(a, b):
            row = 1
            while True:
                if row % 2:
                    if a < row: return row - 1
                    a -= row
                else:
                    if b < row: return row - 1
                    b -= row
                row += 1
        return max(h(red, blue), h(blue, red))

