class Solution {
public:
    int h(int a, int b) {
        int row = 1;
        while (true) {
            if (row % 2) { if (a < row) return row - 1; a -= row; }
            else { if (b < row) return row - 1; b -= row; }
            row++;
        }
    }
    int maxHeightOfTriangle(int red, int blue) {
        return max(h(red, blue), h(blue, red));
    }
};

