class Solution {
    private int h(int a, int b) {
        int row = 1;
        while (true) {
            if (row % 2 == 1) { if (a < row) return row - 1; a -= row; }
            else { if (b < row) return row - 1; b -= row; }
            row++;
        }
    }
    public int maxHeightOfTriangle(int red, int blue) {
        return Math.max(h(red, blue), h(blue, red));
    }
}

